<?php
require 'bootstrap.php';$error='';$id=(int)($_GET['id']??0);$statuses=['research'=>'กำลังศึกษา','negotiating'=>'กำลังเจรจา','proposed'=>'ได้รับข้อเสนอ','signed'=>'ลงนามแล้ว','expired'=>'สิ้นสุด','declined'=>'ไม่เลือก'];
$fields=['company'=>'บริษัทขนส่ง','contact_name'=>'ผู้ติดต่อ','contact_channel'=>'ช่องทางติดต่อ','proposed_rate'=>'อัตราค่าขนส่งที่เสนอ','cod_terms'=>'ค่าบริการ COD','cod_remittance'=>'ระยะเวลานำส่งเงิน COD','pickup_terms'=>'เงื่อนไขเข้ารับพัสดุ','insurance_terms'=>'ประกันเสียหาย / สูญหาย','return_terms'=>'การคืนสินค้า'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 try{
    $id=(int)post('id');$values=[];foreach($fields as $key=>$label){$values[$key]=post($key);if(mb_strlen($values[$key])>(in_array($key,['company','contact_name'])?160:($key==='contact_channel'?300:4000)))throw new RuntimeException('ข้อมูลข้อตกลงยาวเกินกำหนด');}
    if($values['company']===''||!isset($statuses[post('status')]))throw new RuntimeException('กรอกบริษัทและสถานะ');
    $dates=[];foreach(['starts_on','ends_on'] as $key){$raw=post($key);if($raw!==''&&(!($d=DateTimeImmutable::createFromFormat('!Y-m-d',$raw))||$d->format('Y-m-d')!==$raw))throw new RuntimeException('วันที่ไม่ถูกต้อง');$dates[$key]=$raw?:null;}
    if($dates['starts_on']&&$dates['ends_on']&&$dates['starts_on']>$dates['ends_on'])throw new RuntimeException('วันสิ้นสุดต้องไม่ก่อนวันเริ่ม');
    if(post('status')==='signed'&&post('signed_confirm')!=='1')throw new RuntimeException('ต้องยืนยันว่าลงนามจริงแล้ว ไม่ใช่เพียงแผน');
    $params=array_merge(array_values($values),[$dates['starts_on'],$dates['ends_on'],post('status'),post('signed_confirm')==='1'?1:0,$admin['id']]);
    if($id){if(!q('SELECT id FROM shipping_agreements WHERE id=?',[$id])->fetchColumn())throw new RuntimeException('ไม่พบแผน');q('UPDATE shipping_agreements SET company=?,contact_name=?,contact_channel=?,proposed_rate=?,cod_terms=?,cod_remittance=?,pickup_terms=?,insurance_terms=?,return_terms=?,starts_on=?,ends_on=?,status=?,signed_confirm=?,updated_by=? WHERE id=?',array_merge($params,[$id]));}
    else q('INSERT INTO shipping_agreements(company,contact_name,contact_channel,proposed_rate,cod_terms,cod_remittance,pickup_terms,insurance_terms,return_terms,starts_on,ends_on,status,signed_confirm,updated_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',$params);
    flash('บันทึกแผนข้อตกลงแล้ว ไม่ได้เชื่อม API หรือทำสัญญาให้โดยอัตโนมัติ');go('admin/shipping_agreements.php');
 }catch(RuntimeException $ex){$error=$ex instanceof PDOException?'บันทึกไม่สำเร็จ':$ex->getMessage();}
}
$plan=$id?q('SELECT * FROM shipping_agreements WHERE id=?',[$id])->fetch():[];admin_header('แผนข้อตกลงบริษัทขนส่ง');
?>
<div class="notice">ใช้เปรียบเทียบข้อเสนอจริงของร้าน เช่น Flash, J&T, Thailand Post หรือ KEX เท่านั้น ไม่มีอัตราตัวอย่างที่อ้างว่าเป็นราคาจริง และการเพิ่มแผนไม่ใช่การลงนามสัญญา</div><p><a href="?">เพิ่มแผนใหม่</a></p><?php if($error): ?><p class="error"><?=e(t($error))?></p><?php endif ?><form method="post" class="panel commerce-admin-form"><?=csrf()?><input type="hidden" name="id" value="<?=$id?>"><?php foreach($fields as $key=>$label): ?><label><?=e(t($label))?><?php if(in_array($key,['company','contact_name','contact_channel'])): ?><input name="<?=$key?>" value="<?=e($_SERVER['REQUEST_METHOD']==='POST'?post($key):($plan[$key]??''))?>"><?php else: ?><textarea name="<?=$key?>" maxlength="4000"><?=e($_SERVER['REQUEST_METHOD']==='POST'?post($key):($plan[$key]??''))?></textarea><?php endif ?></label><?php endforeach ?><?php field('starts_on','วันเริ่มสัญญา','date',$_SERVER['REQUEST_METHOD']==='POST'?post('starts_on'):($plan['starts_on']??''),false);field('ends_on','วันสิ้นสุดสัญญา','date',$_SERVER['REQUEST_METHOD']==='POST'?post('ends_on'):($plan['ends_on']??''),false); ?><label>สถานะ<select name="status"><?php foreach($statuses as $key=>$label): ?><option value="<?=$key?>" <?=($_SERVER['REQUEST_METHOD']==='POST'?post('status'):($plan['status']??'research'))===$key?'selected':''?>><?=e(t($label))?></option><?php endforeach ?></select></label><label class="checkbox"><input type="checkbox" name="signed_confirm" value="1"> ยืนยันว่ามีการลงนามข้อตกลงจริงแล้ว</label><button>บันทึกแผน</button></form><h2>เปรียบเทียบผู้ให้บริการ</h2><div class="table-wrap"><table><tr><th>บริษัท</th><th>ราคาเสนอ</th><th>COD / นำส่งเงิน</th><th>รับพัสดุ</th><th>ประกัน / คืนสินค้า</th><th>สถานะ</th></tr><?php foreach(q('SELECT * FROM shipping_agreements ORDER BY id DESC') as $p): ?><tr><td><a href="?id=<?=$p['id']?>"><?=e($p['company'])?></a></td><td><?=nl2br(e($p['proposed_rate']))?></td><td><?=nl2br(e($p['cod_terms'].' / '.$p['cod_remittance']))?></td><td><?=nl2br(e($p['pickup_terms']))?></td><td><?=nl2br(e($p['insurance_terms'].' / '.$p['return_terms']))?></td><td><?=e($statuses[$p['status']])?></td></tr><?php endforeach ?></table></div><?php admin_footer(); ?>
